<script setup>
const branding = useBranding()
import {money,today} from '#shared/utils/format.js'
definePageMeta({layout:'auth'})
const {data:catalog,error}=await useFetch('/api/public/catalog')
const route=useRoute()
const requestedService=catalog.value?.services.find(s=>String(s.id)===String(route.query.service))
const requestedLocation=catalog.value?.locations.find(l=>String(l.id)===String(route.query.location))
const {error:formatError}=useFeedback()
const form=reactive({name:'',phone:'',locationId:requestedLocation?.id??null,bookingDate:today(),bookingTime:'14:00',address:'',latitude:null,longitude:null,services:[{serviceId:requestedService?.id??'',qty:1}],notes:''})
const pin=computed({get:()=>({latitude:form.latitude,longitude:form.longitude}),set:point=>{form.latitude=point?.latitude??null;form.longitude=point?.longitude??null}})
const busy=ref(false);const message=ref('');const number=ref('')
const selected=computed(()=>catalog.value?.services.find(s=>s.id===Number(form.services[0].serviceId)))
const price=computed(()=>selected.value?.prices.find(p=>p.locationId===form.locationId)?.price??selected.value?.prices.find(p=>p.locationId===null)?.price??null)
async function submit(){busy.value=true;message.value='';try{const result=await $fetch('/api/public/booking',{method:'POST',body:{...form,services:[{serviceId:Number(form.services[0].serviceId),qty:1}]}});number.value=result.orderNumber}catch(e){message.value=formatError(e)}finally{busy.value=false}}
</script><template><div class="booking-page"><header><NuxtLink to="/" class="brand"><LayoutBrand /></NuxtLink><nav class="booking-public-nav"><NuxtLink to="/#layanan" class="text-link">Layanan & harga</NuxtLink><a href="/dokumentasi.html" class="text-link">Panduan</a></nav></header><main v-if="!number"><p class="eyebrow">WELLNESS, WHEREVER YOU ARE</p><h1>A moment just for you.</h1><p class="muted">Nikmati treatment spa di kenyamanan rumah, hotel, atau villa Anda.</p><form class="panel form-panel mt-8" @submit.prevent="submit"><h2>Booking treatment</h2><div class="form-grid"><label>Nama lengkap<input v-model="form.name" required minlength="2" autocomplete="name" /></label><label>WhatsApp<input v-model="form.phone" type="tel" required placeholder="+62812…" autocomplete="tel" /></label><label class="full">Treatment<select v-model="form.services[0].serviceId" aria-label="Treatment" required><option value="" disabled>Pilih treatment</option><option v-for="s in catalog?.services" :key="s.id" :value="s.id">{{ s.name }} · {{ s.durationMinutes }} menit</option></select></label><label class="full">Area pelayanan<select v-model="form.locationId" aria-label="Area pelayanan"><option :value="null">Bantu saya memilih area</option><option v-for="l in catalog?.locations" :key="l.id" :value="l.id">{{ l.name }}</option></select></label><label>Tanggal<input v-model="form.bookingDate" type="date" :min="today()" required /></label><label>Waktu<input v-model="form.bookingTime" type="time" required /></label><label class="full">Hotel / villa & alamat<textarea v-model="form.address" required minlength="3" rows="3" /></label><div class="full"><LocationPicker v-model="pin" :address="form.address" /></div><label class="full">Catatan<textarea v-model="form.notes" rows="2" placeholder="Preferensi atau instruksi khusus (opsional)" /></label></div><div v-if="selected" class="billing-total"><span>Harga treatment</span><strong>{{ price===null?'Harga belum tersedia untuk area ini':money(price) }}</strong></div><p class="form-hint">Tim kami akan mengonfirmasi jadwal dan ketersediaan therapist sebelum treatment.<span v-if="catalog?.billing?.transportEnabled"> Biaya transport akan dikonfirmasi oleh tim.</span><span v-if="catalog?.billing?.taxEnabled"> Pajak yang berlaku akan dikonfirmasi oleh tim.</span></p><p v-if="message||error" class="error-message">{{ message||error?.data?.statusMessage }}</p><UiButton type="submit" class="w-full mt-4" :loading="busy" :disabled="!!error||!!selected&&price===null">Kirim permintaan booking<UiIcon name="arrow" :size="17" /></UiButton></form></main><main v-else class="booking-success"><div class="empty-icon"><UiIcon name="success" :size="36" /></div><h1>Booking diterima.</h1><p class="muted">Tim kami akan menghubungi WhatsApp Anda untuk konfirmasi.</p><strong class="booking-number">{{ number }}</strong><UiButton variant="secondary" @click="number=''">Booking lainnya</UiButton></main><footer>{{ branding.appName }} · Bali, Indonesia</footer></div></template>

<style scoped>
.booking-public-nav { display:flex; align-items:center; gap:20px; }
@media(max-width:500px) { .booking-public-nav { gap:12px; }.booking-public-nav .text-link { font-size:10px; } }
</style>
